219→// collectCommitChain walks from tip to root following first parent, returns oldest-first.
220→func collectCommitChain(repo *git.Repository, tip plumbing.Hash) ([]*object.Commit, error) {
221→	var chain []*object.Commit
222→	current := tip
223→
224→	reachedRoot := false
225→	for range MaxCommitTraversalDepth {
226→		commit, err := repo.CommitObject(current)
227→		if err != nil {
228→			return nil, fmt.Errorf("failed to get commit %s: %w", current, err)
229→		}
230→		chain = append(chain, commit)
231→
232→		if len(commit.ParentHashes) == 0 {
233→			reachedRoot = true
234→			break
235→		}
236→		current = commit.ParentHashes[0]
237→	}
238→
239→	if !reachedRoot {
240→		return nil, fmt.Errorf("commit chain exceeded %d commits without reaching root; aborting reconciliation", MaxCommitTraversalDepth)
241→	}
242→
243→	// Reverse to oldest-first
244→	for i, j := 0, len(chain)-1; i < j; i, j = i+1, j-1 {
245→		chain[i], chain[j] = chain[j], chain[i]
246→	}
247→
248→	return chain, nil
249→}
