456→// FetchBlobsByHash fetches specific blob objects from the remote by their SHA-1 hashes.
457→// Uses "git fetch origin <hash>" which goes through normal credential helpers,
458→// unlike fetch-pack which bypasses them. Requires the server to support
459→// uploadpack.allowReachableSHA1InWant (GitHub, GitLab, Bitbucket all do).
460→//
461→// If fetching by hash fails, falls back to a full metadata branch fetch.
462→func FetchBlobsByHash(ctx context.Context, hashes []plumbing.Hash) error {
463→	if len(hashes) == 0 {
464→		return nil
465→	}
466→
467→	ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
468→	defer cancel()
469→
470→	// Build fetch args: "git fetch origin <hash1> <hash2> ..."
471→	// This uses the normal transport + credential helpers, unlike fetch-pack.
472→	args := []string{"fetch", "--no-write-fetch-head", "origin"}
473→	for _, h := range hashes {
474→		args = append(args, h.String())
475→	}
476→
477→	fetchCmd := strategy.CheckpointGitCommand(ctx, "origin", args...)
478→	if _, fetchErr := fetchCmd.CombinedOutput(); fetchErr != nil {
479→		logging.Debug(ctx, "fetch-by-hash failed, falling back to full metadata fetch",
480→			slog.Int("blob_count", len(hashes)),
481→			slog.String("error", fetchErr.Error()),
482→		)
483→		// Fallback: full metadata branch fetch (pack negotiation skips already-local objects)
484→		if fallbackErr := FetchMetadataBranch(ctx); fallbackErr != nil {
485→			return fmt.Errorf("fetch-by-hash failed: %w; fallback fetch also failed: %w",
486→				fetchErr, fallbackErr)
487→		}
488→	}
