211→	}
212→
213→	// Verify merged tree contains both local and remote data
214→	tree, err := tipCommit.Tree()
215→	if err != nil {
216→		t.Fatalf("failed to get tree: %v", err)
217→	}
218→
219→	entries := make(map[string]object.TreeEntry)
220→	if err := checkpoint.FlattenTree(repo, tree, "", entries); err != nil {
221→		t.Fatalf("failed to flatten tree: %v", err)
222→	}
223→
224→	// Remote data: metadata.json at root (from initBareWithMetadataBranch)
225→	if _, ok := entries["metadata.json"]; !ok {
226→		t.Error("merged tree missing remote data (metadata.json)")
227→	}
228→	// Local data: ab/cdef012345/metadata.json
229→	if _, ok := entries["ab/cdef012345/metadata.json"]; !ok {
230→		t.Error("merged tree missing local data (ab/cdef012345/metadata.json)")
231→	}
232→
233→	// Original commit message should be preserved (git adds trailing newline)
234→	if tipCommit.Message != "Checkpoint: abcdef012345\n" {
235→		t.Errorf("commit message not preserved: got %q", tipCommit.Message)
236→	}
237→}
